<?php

declare(strict_types=1);

namespace Anthropic\Files;

use Anthropic\Core\Conversion;
use Anthropic\Core\Exceptions\AnthropicException;
use Anthropic\Core\Exceptions\BadRequestException;
use Anthropic\Core\Util;

/**
 * The file has `downloadable: false`. Only files generated by a tool, such as the code execution tool, can be downloaded.
 */
final class FileNotDownloadableException extends BadRequestException
{
    /** @var string */
    protected const DESC = 'Anthropic File Not Downloadable Exception';

    /**
     * `error.details.error_code` from the response body.
     *
     * @return 'file_not_downloadable'
     */
    public function getErrorCode(): string
    {
        return 'file_not_downloadable';
    }

    /**
     * `error.details` from the response body.
     *
     * @throws AnthropicException
     */
    public function getDetails(): FileNotDownloadableErrorDetails
    {
        $details = Conversion::coerce(
            FileNotDownloadableErrorDetails::class,
            value: Util::dig(Util::dig($this->body, 'error'), 'details'),
        );

        if (!$details instanceof FileNotDownloadableErrorDetails) {
            throw new AnthropicException('The response body has no `error.details` object.');
        }

        return $details;
    }
}
